1	package edgefleet
2	
3	import (
4		"bytes"
5		"errors"
6		"io"
7		"strings"
8		"testing"
9	)
10	
11	// slidingIdleBatchLines is the shared fixture for the idle-triggered batch
12	// tests: window 1000, slide 600, two partitions. Both partitions feed the
13	// same keys into overlapping windows; partition 0's watermark (1600) is high
14	// enough to close [0,1000) and [600,1600) while partition 1 sits at 100, so
15	// nothing closes until partition 1 declares idle on physical line 12 (blank
16	// lines 1 and 11 count). Key "é" exercises UTF-8 byte ordering ("a" < "b" <
17	// "é" by bytes). The event at 1300 also opens [1200,2200), which stays open
18	// at effective watermark 1600 and must never be emitted.
19	var slidingIdleBatchLines = []string{
20		``, // line 1: blank, counts toward physical line numbers
21		`{"type":"event","key":"a","time":700,"value":5,"partition":0}`,
22		`{"type":"event","key":"b","time":700,"value":2,"partition":0}`,
23		`{"type":"event","key":"é","time":700,"value":1,"partition":0}`,
24		`{"type":"event","key":"a","time":1000,"value":7,"partition":1}`,
25		`{"type":"event","key":"b","time":1000,"value":3,"partition":1}`,
26		`{"type":"event","key":"é","time":1000,"value":4,"partition":1}`,
27		`{"type":"event","key":"a","time":1300,"value":1,"partition":0}`,
28		`{"type":"watermark","time":1600,"partition":0}`,
29		`{"type":"watermark","time":100,"partition":1}`, // line 10: effective 100, nothing closes
30		``,                              // line 11: blank
31		`{"type":"idle","partition":1}`, // line 12: effective 1600, closes the batch
32	}
33	
34	// slidingIdleBatchOutput is the full batch the line-12 idle declaration
35	// emits: end ascending, then key in UTF-8 byte order, one merged count and
36	// sum per key and window with no partition field.
37	var slidingIdleBatchOutput = []string{
38		`{"key":"a","start":0,"end":1000,"count":1,"sum":5}`,
39		`{"key":"b","start":0,"end":1000,"count":1,"sum":2}`,
40		`{"key":"é","start":0,"end":1000,"count":1,"sum":1}`,
41		`{"key":"a","start":600,"end":1600,"count":3,"sum":13}`,
42		`{"key":"b","start":600,"end":1600,"count":2,"sum":5}`,
43		`{"key":"é","start":600,"end":1600,"count":2,"sum":5}`,
44	}
45	
46	// prefixFailAtWriter buffers full writes until its failAt-th call, which
47	// accepts only prefix bytes before reporting err.
48	type prefixFailAtWriter struct {
49		calls  int
50		failAt int
51		prefix int
52		err    error
53		got    bytes.Buffer
54	}
55	
56	func (w *prefixFailAtWriter) Write(p []byte) (int, error) {
57		w.calls++
58		if w.calls == w.failAt {
59			k := w.prefix
60			if k > len(p) {
61				k = len(p)
62			}
63			w.got.Write(p[:k])
64			return k, w.err
65		}
66		return w.got.Write(p)
67	}
68	
69	// fullErrWriter accepts every write in full, buffering the bytes, but its
70	// failAt-th call still reports err alongside the complete byte count: the
71	// receiver holds the whole record -- every JSON byte and the trailing
72	// newline -- yet the write is a failure.
73	type fullErrWriter struct {
74		calls  int
75		failAt int
76		err    error
77		got    bytes.Buffer
78	}
79	
80	func (w *fullErrWriter) Write(p []byte) (int, error) {
81		w.calls++
82		w.got.Write(p)
83		if w.calls == w.failAt {
84			return len(p), w.err
85		}
86		return len(p), nil
87	}
88	
89	// shortFailAtWriter buffers full writes until its failAt-th call, which
90	// accepts only accept bytes and reports no error.
91	type shortFailAtWriter struct {
92		calls  int
